import java.net.URI;import java.net.http.*;import java.time.Duration;
public class Healthcheck {public static void main(String[] args)throws Exception{String port=System.getenv().getOrDefault("SERVER_PORT","8080");try(var http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build()){var response=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/actuator/health")).timeout(Duration.ofSeconds(3)).GET().build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)System.exit(1);}}}
